import sqlite3
db = sqlite3.connect(":memory:")
db.executescript('''
CREATE TABLE c(id INT, name TEXT);
CREATE TABLE o(id INT, cid INT, status TEXT);
INSERT INTO c VALUES (1,'a'),(2,'b'),(3,'c');
INSERT INTO o VALUES (10,1,'paid'),(11,1,'rto'),(12,2,'rto');
''')
q1 = "SELECT COUNT(*) FROM c LEFT JOIN o ON o.cid=c.id WHERE o.status='paid'"
q2 = "SELECT COUNT(*) FROM c LEFT JOIN o ON o.cid=c.id AND o.status='paid'"
print(db.execute(q1).fetchone()[0], db.execute(q2).fetchone()[0])

import sqlite3
db = sqlite3.connect(":memory:")
db.executescript('''
CREATE TABLE orders(id INT, total INT);
CREATE TABLE ship(order_id INT);
INSERT INTO orders VALUES (1,100),(2,50);
INSERT INTO ship VALUES (1),(1),(1);
''')
r = db.execute('''SELECT SUM(o.total), COUNT(s.order_id)
FROM orders o LEFT JOIN ship s ON s.order_id = o.id''').fetchone()
print(r)
